 'fixtures',jsonb_build_object('auth',(select count(*)from auth.users where id::text like 'a1a154%'),'profile',(select count(*)from profiles where id::text like 'a1a154%'),'storage',(select count(*)from storage.objects where name like 'a1a154%'),'pending_photo_deletion',(select count(*)from spot_private.photo_cutover_deletions where user_id::text like 'a1a154%'and not completed),'completed_photo_receipts',(select count(*)from spot_private.photo_cutover_deletions where user_id::text like 'a1a154%'and completed)),
