 'functions',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'hash',md5(p.prosrc),'config',p.proconfig))from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in('public','spot_private')and p.proname in('retention_phase_a_batch','phase_a_candidates','phase_a_held','phase_a_fk_check','retention_phase_a_status','photo_metadata_purge')),
